query LeaderboardGetGolfTournamentLeaderboard(
  $input: GetGolfTournamentLeaderboardInput!
) {
  getGolfTournamentLeaderboard(input: $input) {
    tournamentId
    activeRound
    playoffRoundNo
    tournamentStatus
    cutLine {
      cut
      required
      roundNumber
    }
    standingsFeed {
      ...leaderboardGetGolfTournamentLeaderboardFieldsQuery
    }
  }
}
fragment leaderboardGetGolfTournamentLeaderboardFieldsQuery on GolfTournamentLeaderboardStandingsFeed {
  standings {
    ...leaderboardGolfTeamFieldsQuery
  }
  pageInfo {
    hasNextPage
    totalCount
  }
}

fragment leaderboardGolfTeamFieldsQuery on GolfTournamentLeaderboardStanding {
  players {
    id
    displayName
    country
    lastName
    firstName
    status
  }
  status
  position {
    value
    displayValue
    order
    format
  }
  toPar
  holesThrough
  toParToday
  startHole
  currentRound
  teamId
  courseId
  l1Event
  totalScore
  roundInfo {
    courseId
    teeTime
    startHole
    roundNo
    score {
      displayValue
      value
    }
    toPar {
      displayValue
      value
    }
  }
}
